glsl3.vert:
precision highp float;
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
layout(std140) uniform FxVert {
  vec4 fxView;
};
vec4 vert () {
  vec2 p = a_position.xy + fxView.zw;
  v_uv = a_texCoord;
  v_color = a_color;
  return vec4(p.x / fxView.x * 2.0 - 1.0, 1.0 - p.y / fxView.y * 2.0, 0.0, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D mainTexture;
vec4 frag () {
  vec4 t = texture(mainTexture, v_uv);
  #if SPRITE_MODE
    float a = t.a * v_color.a;
    return vec4(t.rgb * v_color.rgb * a, a);
  #else
    vec3 rgb = mix(mix(v_color.rgb, vec3(1.0), t.r), vec3(0.102, 0.063, 0.2), t.g);
    float a = t.a * v_color.a;
    return vec4(rgb * a, a);
  #endif
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 v_uv;
varying vec4 v_color;
  uniform vec4 fxView;
vec4 vert () {
  vec2 p = a_position.xy + fxView.zw;
  v_uv = a_texCoord;
  v_color = a_color;
  return vec4(p.x / fxView.x * 2.0 - 1.0, 1.0 - p.y / fxView.y * 2.0, 0.0, 1.0);
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D mainTexture;
vec4 frag () {
  vec4 t = texture2D(mainTexture, v_uv);
  #if SPRITE_MODE
    float a = t.a * v_color.a;
    return vec4(t.rgb * v_color.rgb * a, a);
  #else
    vec3 rgb = mix(mix(v_color.rgb, vec3(1.0), t.r), vec3(0.102, 0.063, 0.2), t.g);
    float a = t.a * v_color.a;
    return vec4(rgb * a, a);
  #endif
}
void main() { gl_FragColor = frag(); }
